/*
 * A307528  G.f. A(x) satisfies: A(x) = 1 + x^2*A(x)^2/(1 - x*A(x) -
 *          x^2*A(x)^2 - x^3*A(x)^3).
 * https://oeis.org/A307528
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   A(x) satisfies A(x) = 1 + x^2*A(x)^2/(1 - x*A(x) - x^2*A(x)^2 -
 *            x^3*A(x)^3). The sequence is generated by the recurrence a(0)=1,
 *            a(1)=0 a(n) = b2(n‑1) - a(n‑1) + b3(n‑2) - b3(n‑3) + b4(n‑3)
 *            (n≥2) where b2(k)=∑_{i=0}^{k} a(i)*a(k‑i), b3(k)=∑_{i=0}^{k}
 *            a(i)*b2(k‑i), b4(k)=∑_{i=0}^{k} a(i)*b3(k‑i)
 * Range:     u8 n <= 8, u16 n <= 13, u32 n <= 22, u64 n <= 30, u128 n <= 30,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static tables for memoisation */
    static seq_t *A = NULL;     /* a[n]          */
    static seq_t *B2 = NULL;    /* b2[n]         */
    static seq_t *B3 = NULL;    /* b3[n]         */
    static seq_t *B4 = NULL;    /* b4[n]         */
    static size_t cap = 0;      /* current allocated size */
    static idx_t max_idx = 0;   /* highest index stored */
    size_t needed = n + 1;

    /* grow tables if necessary */
    if (needed > cap) {
        /* allocate one more element for safety */
        size_t new_cap = needed;
        A   = (seq_t*)realloc(A, new_cap * sizeof(seq_t));
        B2  = (seq_t*)realloc(B2, new_cap * sizeof(seq_t));
        B3  = (seq_t*)realloc(B3, new_cap * sizeof(seq_t));
        B4  = (seq_t*)realloc(B4, new_cap * sizeof(seq_t));
        cap = new_cap;
    }

    /* initialise first two values if needed */
    if (max_idx == 0) {
        if (cap > 0) {
            A[0]  = 1;
            B2[0] = 1; B3[0] = 1; B4[0] = 1;
        }
        if (cap > 1) {
            A[1]  = 0;
            B2[1] = 0; B3[1] = 0; B4[1] = 0;
        }
        max_idx = (cap > 1) ? 1 : 0;
    }

    /* compute successive terms up to n */
    for (idx_t k = max_idx + 1; k <= n; ++k) {
        seq_t new_a;
        if (k == 0) {
            new_a = 1; /* already set */
        } else if (k == 1) {
            new_a = 0; /* already set */
        } else {
            /* recurrence using previously computed values */
            seq_t term = B2[k-1];       /* b2(n-1)   */
            term = term - A[k-1];       /* - a(n-1)  */
            if (k >= 2) term = term + B3[k-2];   /* + b3(n-2) */
            if (k >= 3) term = term - B3[k-3];   /* - b3(n-3) */
            if (k >= 3) term = term + B4[k-3];   /* + b4(n-3) */
            new_a = term;
        }
        A[k] = new_a;

        /* compute b2[k] = Σ a[i]*a[k-i] */
        seq_t sum2 = 0;
        for (idx_t i = 0; i <= k; ++i) {
            sum2 += A[i] * A[k-i];
        }
        B2[k] = sum2;

        /* compute b3[k] = Σ a[i]*b2[k-i] */
        seq_t sum3 = 0;
        for (idx_t i = 0; i <= k; ++i) {
            sum3 += A[i] * B2[k-i];
        }
        B3[k] = sum3;

        /* compute b4[k] = Σ a[i]*b3[k-i] */
        seq_t sum4 = 0;
        for (idx_t i = 0; i <= k; ++i) {
            sum4 += A[i] * B3[k-i];
        }
        B4[k] = sum4;
    }

    max_idx = n;
    return A[n];
}
